//! A document's fonts as the fork finds them, read without loading a page.
//!
//! Ports `services/src/features/fonts/DocumentFontReader.ts`: the faces a
//! document's dictionaries name and what each program is, the engine's
//! fonts, the fonts a write would draw text with, and programs by hash.
//! Facts only: what a font allows is decided above the worker, from these.
//! The `document.fonts.list`, `document.fonts.resolve` and
//! `document.fonts.program` kinds answer with them.

use serde::Serialize;

use super::list::{
    DocumentFaceFacts, Embedded, FontListFacts, FontProgramFacts, ProgramPermission,
    document_fonts_of, document_program_for_name,
};
use super::{FontFormat, FontRegistry, ProgramInfo, hex, thousandths};
use crate::access::OwnedDocument;
use crate::error::{EngineError, EngineErrorCode};
use crate::features::annotation::rich_text::standard_face;
use crate::features::annotation::vocabulary::StandardFont;
use crate::identity::AnnotationRef;

/// `FontResolveRun`: a run of text and the font it asks for, by the name
/// `fontFamily` takes or by its face.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FontResolveRun {
    Named { text: String, font_family: String },
    Face { text: String, family: String, weight: i32, italic: bool },
}

impl FontResolveRun {
    fn text(&self) -> &str {
        match self {
            Self::Named { text, .. } | Self::Face { text, .. } => text,
        }
    }

    /// One run off the wire. A run that has `fontFamily` names its font by
    /// it, whatever else it has (`'fontFamily' in run`). `weight` takes
    /// `ToInt32` of the number, as the `Int32Array` the TypeScript writes it
    /// into does.
    pub fn from_wire(value: &serde_json::Value) -> Result<Self, EngineError> {
        let refused = |what: &str| {
            EngineError::with_message(
                EngineErrorCode::WireFormat,
                format!("a 'document.fonts.resolve' run's {what}"),
            )
        };
        let object = value.as_object().ok_or_else(|| refused("shape: not an object"))?;
        let string = |name: &str| {
            object
                .get(name)
                .and_then(serde_json::Value::as_str)
                .map(str::to_owned)
                .ok_or_else(|| refused(&format!("'{name}' is not a string")))
        };
        let text = string("text")?;
        if object.contains_key("fontFamily") {
            return Ok(Self::Named { text, font_family: string("fontFamily")? });
        }
        let weight = object
            .get("weight")
            .and_then(serde_json::Value::as_f64)
            .map(crate::js_number::to_int32)
            .ok_or_else(|| refused("'weight' is not a number"))?;
        let italic = object
            .get("italic")
            .and_then(serde_json::Value::as_bool)
            .ok_or_else(|| refused("'italic' is not a boolean"))?;
        Ok(Self::Face { text, family: string("family")?, weight, italic })
    }
}

/// `ResolvedRunFacts['source']`.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "kebab-case")]
pub enum RunSource {
    Standard,
    Engine,
    DocumentProgram,
    DocumentFont,
}

/// `ResolvedRunFacts`: what the fork's resolver says about one run.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ResolvedRunFacts {
    pub source: RunSource,
    pub engine_font: Option<String>,
    pub object_number: u32,
    pub display_sha256: Option<String>,
    pub base_font_name: Option<String>,
    pub family_name: String,
    pub weight: i32,
    pub italic: bool,
    pub degraded: bool,
    pub fallbacks: Vec<String>,
}

/// What `DocumentFontReader.resolve` answers.
#[derive(Debug, Clone, PartialEq, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct FontResolutionFacts {
    pub runs: Vec<ResolvedRunFacts>,
    pub missing_characters: Vec<String>,
}

/// `readDocumentFaces`: the faces a document's fonts are, with the facts
/// about each program (the fork's walk). `Unknown` when the fork answers no
/// snapshot.
pub fn read_document_faces(
    document: &pdfium::Document,
) -> Result<Vec<DocumentFaceFacts>, EngineError> {
    let faces = document.font_faces().map_err(super::engine_error)?.ok_or_else(|| {
        EngineError::with_message(EngineErrorCode::Unknown, "EPDFFontFaces_Load failed")
    })?;
    Ok(faces
        .into_iter()
        .map(|face| DocumentFaceFacts {
            family_name: face.family_name.unwrap_or_default(),
            weight: face.weight,
            italic: face.italic,
            programs: face.programs.into_iter().map(program_facts).collect(),
        })
        .collect())
}

/// `programFacts`: one program's facts, named as the wire names them.
fn program_facts(program: pdfium::DocumentFontProgram) -> FontProgramFacts {
    let (ascent, descent) = thousandths(program.metrics);
    FontProgramFacts {
        object_number: program.object_number,
        format: FontFormat::of_program(program.format),
        embedded: match program.embedding {
            Some(pdfium::FontEmbedding::Whole) => Embedded::Whole,
            Some(pdfium::FontEmbedding::Subset) => Embedded::Subset,
            _ => Embedded::None,
        },
        post_script_name: program.postscript_name.filter(|name| !name.is_empty()),
        permission: ProgramPermission::from_code(program.embedding_permission),
        maps_unicode: program.maps_unicode,
        sha256: program.sha256.map(|hash| hex(&hash)),
        display_sha256: program.display_sha256.map(|hash| hex(&hash)),
        ascent,
        descent,
    }
}

/// `DocumentFontReader.facts`: everything the document's font list is made
/// from.
pub fn facts(
    document: &pdfium::Document,
    fonts: &FontRegistry,
) -> Result<FontListFacts, EngineError> {
    Ok(FontListFacts {
        faces: read_document_faces(document)?,
        engine_fonts: fonts.engine_font_facts(),
        fallbacks: fonts.fallback_order(),
    })
}

/// The face a run asks for (`faceOfRun`).
struct RunFace {
    family: String,
    weight: i32,
    italic: bool,
    program: i32,
}

/// `faceOfRun`: the face a run asks for, found as a write finds it: a
/// standard name's, an engine font's, a document font's (with the program a
/// write would name, when new text can be written in it), or a family.
fn face_of_run(run: &FontResolveRun, facts: &FontListFacts, fonts: &FontRegistry) -> RunFace {
    let name = match run {
        FontResolveRun::Face { family, weight, italic, .. } => {
            return RunFace {
                family: family.clone(),
                weight: *weight,
                italic: *italic,
                program: 0,
            };
        }
        FontResolveRun::Named { font_family, .. } => font_family.as_str(),
    };
    if let Some(standard) = StandardFont::from_family(name) {
        let (family, weight, italic) = standard_face(standard);
        let weight = i32::try_from(weight).unwrap_or(400);
        return RunFace { family: family.to_owned(), weight, italic, program: 0 };
    }
    if let Some(identity) = fonts.describe(name) {
        return RunFace {
            family: identity.family_name,
            weight: identity.weight,
            italic: identity.italic,
            program: 0,
        };
    }
    if let Some(font) = document_fonts_of(&facts.faces).into_iter().find(|font| font.name == name) {
        let program = document_program_for_name(&facts.faces, name)
            .filter(|choice| choice.choosable)
            .map_or(0, |choice| i32::try_from(choice.object_number).unwrap_or(0));
        return RunFace {
            family: font.face.family_name,
            weight: font.face.weight,
            italic: font.face.italic,
            program,
        };
    }
    // `faceForFontName` with no describer: the name as a family.
    RunFace { family: name.to_owned(), weight: 400, italic: false, program: 0 }
}

/// `DocumentFontReader.resolve`: the fonts a write would draw each run in,
/// and the characters no font has. `annotation` is the box being edited,
/// opened off the document without loading its page.
pub fn resolve(
    owned: &OwnedDocument,
    fonts: &FontRegistry,
    annotation: Option<&AnnotationRef>,
    runs: &[FontResolveRun],
    facts: &FontListFacts,
) -> Result<FontResolutionFacts, EngineError> {
    let document = owned.document();
    let asked: Vec<pdfium::FontResolveRun> = runs
        .iter()
        .map(|run| {
            let face = face_of_run(run, facts, fonts);
            pdfium::FontResolveRun {
                text: run.text().to_owned(),
                family: face.family,
                weight: face.weight,
                italic: face.italic,
                program: face.program,
            }
        })
        .collect();
    let opened = match annotation {
        Some(reference) => {
            let page_index = owned.page_index(reference.page())?;
            let index = crate::features::annotation::write::resolve::resolve_annotation_index_raw(
                document, page_index, reference,
            )?;
            let found = document.raw_annotation(page_index, index).ok_or_else(|| {
                EngineError::with_message(EngineErrorCode::NotFound, "annotation not found")
            })?;
            Some(found)
        }
        None => None,
    };
    let resolution =
        document.resolve_fonts(opened.as_ref(), &asked).map_err(super::engine_error)?.ok_or_else(
            || EngineError::with_message(EngineErrorCode::Unknown, "EPDFDoc_ResolveFonts failed"),
        )?;
    let runs = resolution
        .runs
        .into_iter()
        .map(|run| ResolvedRunFacts {
            source: match run.source {
                Some(pdfium::FontSource::Registered) => RunSource::Engine,
                Some(pdfium::FontSource::DocumentProgram) => RunSource::DocumentProgram,
                Some(pdfium::FontSource::DocumentFont) => RunSource::DocumentFont,
                _ => RunSource::Standard,
            },
            engine_font: run.registered_font.and_then(|id| fonts.key_for_id(id)),
            object_number: run.program_object_number,
            display_sha256: run.display_sha256.map(|hash| hex(&hash)),
            base_font_name: run.base_font_name.filter(|name| !name.is_empty()),
            family_name: run.family_name.unwrap_or_default(),
            weight: run.weight,
            italic: run.italic,
            degraded: run.degraded,
            fallbacks: run.fallbacks.into_iter().filter_map(|id| fonts.key_for_id(id)).collect(),
        })
        .collect();
    Ok(FontResolutionFacts { runs, missing_characters: resolution.missing_characters })
}

/// `DocumentFontReader.program`: a program the document's fonts name, by
/// its display hash: an engine font's or a document program's. Its coverage
/// and metrics, and with `data` the bytes a browser loads. `NotFound` for a
/// hash neither names.
pub fn program(
    document: &pdfium::Document,
    fonts: &FontRegistry,
    display_hash: &str,
    data: bool,
) -> Result<(ProgramInfo, Option<Vec<u8>>), EngineError> {
    if let Some(info) = fonts.program_info(display_hash)? {
        let bytes = if data { fonts.program_bytes(display_hash)? } else { None };
        return Ok((info, bytes));
    }
    let faces = read_document_faces(document)?;
    let found = faces.iter().flat_map(|face| &face.programs).find(|candidate| {
        candidate.display_sha256.as_deref() == Some(display_hash) && candidate.object_number > 0
    });
    let (Some(program), Some(hash)) = (found, bytes_of_hex(display_hash)) else {
        return Err(EngineError::with_message(
            EngineErrorCode::NotFound,
            format!("no font program {display_hash}"),
        ));
    };
    // By the hash: a stream two font dictionaries read differently is two
    // programs.
    let covers = document
        .font_display_program_coverage(&hash)
        .map_err(super::engine_error)?
        .into_iter()
        .map(Into::into)
        .collect();
    let bytes = if data {
        Some(
            document
                .font_display_program_data(&hash)
                .map_err(super::engine_error)?
                .unwrap_or_default(),
        )
    } else {
        None
    };
    Ok((ProgramInfo { covers, ascent: program.ascent, descent: program.descent }, bytes))
}

/// `bytesOfHex`: the 32 bytes a SHA-256's hex names. Only a display hash
/// the reader wrote reaches it, so anything else is `None`.
fn bytes_of_hex(hex: &str) -> Option<[u8; 32]> {
    if hex.len() != 64 || !hex.is_ascii() {
        return None;
    }
    let mut out = [0u8; 32];
    for (at, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[at * 2..at * 2 + 2], 16).ok()?;
    }
    Some(out)
}

/// `FontsSeen`: what a tracked session's fonts were when last read.
#[derive(Debug, Clone, PartialEq)]
pub struct FontsSeen {
    /// The fork's fingerprint of the document's faces.
    fingerprint: [u8; 32],
    /// The document fonts a list shows.
    document_fonts: Vec<super::list::ListedDocumentFont>,
}

/// `fontsFingerprintOf`.
fn fonts_fingerprint(document: &pdfium::Document) -> Result<[u8; 32], EngineError> {
    document.fonts_fingerprint().ok_or_else(|| {
        EngineError::with_message(EngineErrorCode::Unknown, "EPDFDoc_GetFontsFingerprint failed")
    })
}

/// `listedDocumentFontsOf`: the document fonts a list shows; the engine's
/// fonts don't change with a write.
fn listed_document_fonts_of(
    document: &pdfium::Document,
) -> Result<Vec<super::list::ListedDocumentFont>, EngineError> {
    Ok(super::list::listed_document_fonts(&read_document_faces(document)?))
}

/// `trackFontChanges`: from now on, [`fonts_changed_since`] tells of every
/// change to the session's fonts. A session already tracked stays as it is.
pub fn track_font_changes(
    session: &mut crate::session::document::DocumentSession,
) -> Result<(), EngineError> {
    if session.fonts_seen().is_some() {
        return Ok(());
    }
    let document = session.document()?.document();
    let seen = FontsSeen {
        fingerprint: fonts_fingerprint(document)?,
        document_fonts: listed_document_fonts_of(document)?,
    };
    session.set_fonts_seen(seen);
    Ok(())
}

/// `fontsChangedSince`: whether the fonts the session's list shows changed
/// since this was last asked (or since tracking began); false for a session
/// not tracked. The fingerprint says whether anything about the faces moved;
/// only then is the list compared, since a face the list doesn't show (a
/// standard font's stand-in) moves it too.
pub fn fonts_changed_since(
    session: &mut crate::session::document::DocumentSession,
) -> Result<bool, EngineError> {
    let Some(before) = session.fonts_seen() else { return Ok(false) };
    let document = session.document()?.document();
    let fingerprint = fonts_fingerprint(document)?;
    if fingerprint == before.fingerprint {
        return Ok(false);
    }
    let document_fonts = listed_document_fonts_of(document)?;
    let changed = document_fonts != before.document_fonts;
    session.set_fonts_seen(FontsSeen { fingerprint, document_fonts });
    Ok(changed)
}

/**
 * How Acrobat draws an ink stroke (`/InkList`) when it writes the appearance,
 * and so how the runtime draws it (`cpdf_ink_curves.h` in the fork): cubic
 * Béziers fitted to the points as Schneider fits digitized curves ("An
 * Algorithm for Automatically Fitting Digitized Curves", Graphics Gems,
 * 1990), without his Newton step. Checked against the appearances Acrobat
 * wrote, to 0.001 pt, segment for segment:
 *
 * - Repeated points in a row count once.
 * - A piece of the stroke is one cubic. At the stroke's ends it leaves and
 *   arrives along the first and last segment; where two pieces meet, along
 *   the line from the point before to the point after (no direction when
 *   those are the same point: the stroke turns straight back).
 * - A piece of two points gets handles a third of its length.
 * - A longer piece gets the least-squares cubic over its points, placed by
 *   chord length. It stays one piece when every point is within the
 *   tolerance of the curve, at its place, and the curve is within the
 *   tolerance of the lines between the points. Otherwise it splits at its
 *   worst point and both halves are fitted again.
 * - A stroke of one point is a dot: a circle of radius 0.5, filled and
 *   stroked.
 *
 * The fit is the same in page space: it measures only distances and
 * directions, which a flip and a shift keep.
 */
import { bezierAt, flattenBezier, pathNumber } from './bezier';
import type { Point } from './types';

/**
 * How far the curves may stray, in points. Acrobat's lies above 1.2747 and at
 * most 1.5062 (the dense zigzag in the tests tells), at any width.
 */
export const INK_CURVE_TOLERANCE = Math.SQRT2;

/** The radius of the dot a stroke of one point draws. */
export const INK_DOT_RADIUS = 0.5;

/** One cubic of a stroke, from the end of the one before (or the stroke's start). */
export interface InkCubic {
  control1: Point;
  control2: Point;
  end: Point;
}

/** One stroke as it is drawn: cubics from its first point, or a dot. */
export type InkStrokeCurves =
  | { kind: 'curves'; start: Point; cubics: InkCubic[] }
  | { kind: 'dot'; center: Point };

/**
 * A piece of the stroke to fit: its first and last point, and the directions
 * the curve leaves the first along and arrives at the last against (pointing
 * back into the curve), both unit or none.
 */
interface Piece {
  first: number;
  last: number;
  leaving: Point;
  arriving: Point;
}

const plus = (a: Point, b: Point): Point => ({ x: a.x + b.x, y: a.y + b.y });
const minus = (a: Point, b: Point): Point => ({ x: a.x - b.x, y: a.y - b.y });
const times = (a: Point, s: number): Point => ({ x: a.x * s, y: a.y * s });
const dot = (a: Point, b: Point): number => a.x * b.x + a.y * b.y;
const distance = (a: Point, b: Point): number => Math.hypot(a.x - b.x, a.y - b.y);

/** `v` at length 1; no direction (0, 0) when it has no length. */
function unit(v: Point): Point {
  const length = Math.hypot(v.x, v.y);
  return length === 0 ? { x: 0, y: 0 } : { x: v.x / length, y: v.y / length };
}

/** Where each point of the piece sits along it, 0 to 1, by the length of the lines between them. */
function chordLengthPlaces(points: Point[], piece: Piece): number[] {
  const places = [0];
  for (let i = piece.first + 1; i <= piece.last; i++)
    places.push(places[places.length - 1]! + distance(points[i]!, points[i - 1]!));
  const length = places[places.length - 1]!;
  return places.map((place) => place / length);
}

/**
 * The cubic from the piece's first point to its last, along its two
 * directions, whose handle lengths put it closest to the points at their
 * places (least squares). Handles that come out shorter than a millionth of
 * the piece's span, or backwards, are a third of the span instead.
 */
function leastSquaresCubic(points: Point[], piece: Piece, places: number[]): Point[] {
  const start = points[piece.first]!;
  const end = points[piece.last]!;
  let c00 = 0;
  let c01 = 0;
  let c11 = 0;
  let x0 = 0;
  let x1 = 0;
  places.forEach((u, i) => {
    const rest = 1 - u;
    const b0 = rest * rest * rest;
    const b1 = 3 * u * rest * rest;
    const b2 = 3 * u * u * rest;
    const b3 = u * u * u;
    const a0 = times(piece.leaving, b1);
    const a1 = times(piece.arriving, b2);
    c00 += dot(a0, a0);
    c01 += dot(a0, a1);
    c11 += dot(a1, a1);
    const off = minus(
      points[piece.first + i]!,
      plus(plus(times(start, b0), times(start, b1)), plus(times(end, b2), times(end, b3))),
    );
    x0 += dot(a0, off);
    x1 += dot(a1, off);
  });
  const det = c00 * c11 - c01 * c01;
  let leavingLength = det === 0 ? 0 : (x0 * c11 - x1 * c01) / det;
  let arrivingLength = det === 0 ? 0 : (c00 * x1 - c01 * x0) / det;
  const span = distance(end, start);
  if (leavingLength < 1e-6 * span || arrivingLength < 1e-6 * span) {
    leavingLength = span / 3;
    arrivingLength = span / 3;
  }
  return [
    start,
    plus(start, times(piece.leaving, leavingLength)),
    plus(end, times(piece.arriving, arrivingLength)),
    end,
  ];
}

/** The piece's point farthest from the curve at its place: the square of that distance, and which (the last of equals). */
function worstPoint(
  points: Point[],
  piece: Piece,
  places: number[],
  cubic: Point[],
): { squared: number; index: number } {
  const [p0, p1, p2, p3] = cubic as [Point, Point, Point, Point];
  let worst = { squared: 0, index: Math.floor((piece.last - piece.first + 1) / 2) + piece.first };
  for (let i = piece.first + 1; i < piece.last; i++) {
    const off = minus(bezierAt(p0, p1, p2, p3, places[i - piece.first]!), points[i]!);
    const squared = dot(off, off);
    if (squared >= worst.squared) worst = { squared, index: i };
  }
  return worst;
}

function distanceToSegment(p: Point, a: Point, b: Point): number {
  const ab = minus(b, a);
  const lengthSquared = dot(ab, ab);
  const t =
    lengthSquared === 0 ? 0 : Math.min(1, Math.max(0, dot(minus(p, a), ab) / lengthSquared));
  return distance(p, plus(a, times(ab, t)));
}

/** How far the curve strays from the lines between the piece's points: the farthest of 65 places along it, each from its nearest line. */
function distanceFromLines(points: Point[], piece: Piece, cubic: Point[]): number {
  const [p0, p1, p2, p3] = cubic as [Point, Point, Point, Point];
  let farthest = 0;
  for (let k = 0; k <= 64; k++) {
    const at = bezierAt(p0, p1, p2, p3, k / 64);
    let nearest = Infinity;
    for (let i = piece.first; i < piece.last; i++)
      nearest = Math.min(nearest, distanceToSegment(at, points[i]!, points[i + 1]!));
    farthest = Math.max(farthest, nearest);
  }
  return farthest;
}

/**
 * The stroke as Acrobat draws it: the cubics that fit its points, or a dot
 * for one point; `null` for a stroke with no points.
 */
export function fitInkStroke(
  stroke: readonly Point[],
  tolerance: number = INK_CURVE_TOLERANCE,
): InkStrokeCurves | null {
  const points: Point[] = [];
  for (const point of stroke) {
    const previous = points[points.length - 1];
    if (!previous || previous.x !== point.x || previous.y !== point.y) points.push(point);
  }
  if (points.length === 0) return null;
  if (points.length === 1) return { kind: 'dot', center: points[0]! };

  // The pieces still to fit, the next on top: a split piece's first half is
  // fitted (and split) before its second, so the cubics come out in order.
  const cubics: InkCubic[] = [];
  const last = points.length - 1;
  const pending: Piece[] = [
    {
      first: 0,
      last,
      leaving: unit(minus(points[1]!, points[0]!)),
      arriving: unit(minus(points[last - 1]!, points[last]!)),
    },
  ];
  while (pending.length > 0) {
    const piece = pending.pop()!;
    const start = points[piece.first]!;
    const end = points[piece.last]!;
    if (piece.last - piece.first === 1) {
      const handle = distance(end, start) / 3;
      cubics.push({
        control1: plus(start, times(piece.leaving, handle)),
        control2: plus(end, times(piece.arriving, handle)),
        end,
      });
      continue;
    }
    const places = chordLengthPlaces(points, piece);
    const cubic = leastSquaresCubic(points, piece, places);
    const worst = worstPoint(points, piece, places, cubic);
    if (
      worst.squared < tolerance * tolerance &&
      distanceFromLines(points, piece, cubic) < tolerance
    ) {
      cubics.push({ control1: cubic[1]!, control2: cubic[2]!, end });
      continue;
    }
    // The halves meet at the worst point, along the line from the point
    // before it to the point after.
    const split = worst.index;
    const back = unit(minus(points[split - 1]!, points[split + 1]!));
    pending.push({
      first: split,
      last: piece.last,
      leaving: times(back, -1),
      arriving: piece.arriving,
    });
    pending.push({ first: piece.first, last: split, leaving: piece.leaving, arriving: back });
  }
  return { kind: 'curves', start: points[0]!, cubics };
}

/** The stroke's curves as SVG path data. */
export function inkCurvesPath(curves: Extract<InkStrokeCurves, { kind: 'curves' }>): string {
  const at = (point: Point) => `${pathNumber(point.x)} ${pathNumber(point.y)}`;
  return [
    `M ${at(curves.start)}`,
    ...curves.cubics.map(
      ({ control1, control2, end }) => `C ${at(control1)} ${at(control2)} ${at(end)}`,
    ),
  ].join(' ');
}

/** How far the points along the curves (`inkCurvesPolyline`) may stray from them. */
const POLYLINE_TOLERANCE = 0.05;

/** Points along the stroke's curves, close enough to stand in for them in a hit test. */
export function inkCurvesPolyline(curves: Extract<InkStrokeCurves, { kind: 'curves' }>): Point[] {
  const points = [curves.start];
  let from = curves.start;
  for (const { control1, control2, end } of curves.cubics) {
    points.push(...flattenBezier(from, control1, control2, end, POLYLINE_TOLERANCE));
    from = end;
  }
  return points;
}
